"""Print the key numbers, as markdown tables, and save them to results/tables.md.

Run:  python code/06_tables.py
"""
import json
import sys
from pathlib import Path

import pandas as pd

sys.stdout.reconfigure(encoding="utf-8")
RES = Path(__file__).resolve().parents[1] / "results"
res = pd.read_csv(RES / "experiment_results.csv")
det = pd.read_csv(RES / "detection_results.csv")
on = pd.read_csv(RES / "onsets.csv")
# OKF frontmatter so the generated file is a valid concept in the bundle
out = ["---\ntype: results\ntitle: Result tables\n"
       "description: All result tables, generated by code/06_tables.py.\n"
       "generated: {by: process:code/06_tables.py}\n---\n"]

out.append("## Table: onsets\n")
out.append(on[["file", "onset_t", "score_vs_F0", "feat_score_vs_F0", "top_feature", "locatable"]]
           .round(2).to_markdown(index=False))

out.append("\n\n## Table: protocol summary (macro-F1 mean ± sd over 5 seeds)\n")
g = res.groupby(["exp", "scope", "features", "model"])["macro_f1"].agg(["mean", "std"]).reset_index()
g["macro_f1"] = g["mean"].map("{:.3f}".format) + " ± " + g["std"].map("{:.3f}".format)
out.append(g.drop(columns=["mean", "std"]).to_markdown(index=False))

out.append("\n\n## Table: cross-mode, seed 0, with block-bootstrap 95% CI and per-class recall\n")
cm = res[(res.exp == "E3b_cross_mode") & (res.seed == 0)]
cols = ["scope", "features", "model", "macro_f1", "f1_ci_lo", "f1_ci_hi", "bal_acc"] + \
       [c for c in res.columns if c.startswith("recall_F")]
out.append(cm[cols].round(3).to_markdown(index=False))

out.append("\n\n## Table: detection (held-out threshold, 12_detection_heldout.py)\n")
# 12_detection_heldout.py writes false_alarm_rate + false_alarm_basis; the first version wrote false_alarm_rate_pre
fa_cols = ["false_alarm_rate", "false_alarm_basis"] if "false_alarm_rate" in det.columns else ["false_alarm_rate_pre"]
out.append(det[["detector", "file", "fault", "onset_t", "detected", "delay_s"] + fa_cols +
               ["post_alarm_fraction"]].round(3).to_markdown(index=False))

cnn_path = RES / "cnn_results.csv"
if cnn_path.exists():
    cnn = pd.read_csv(cnn_path)
    out.append("\n\n## Table: 1D CNN on raw waveforms (macro-F1 mean ± sd over seeds, 11_cnn.py)\n")
    g = cnn.groupby(["exp", "scope", "input"])["macro_f1"].agg(["mean", "std"]).reset_index()
    g["macro_f1"] = g["mean"].map("{:.3f}".format) + " ± " + g["std"].map("{:.3f}".format)
    out.append(g.drop(columns=["mean", "std"]).to_markdown(index=False))
checks = Path(__file__).resolve().parents[1] / "results_checks"
if checks.exists():
    meta = [json.loads(f.read_text(encoding="utf-8")) for f in checks.glob("H6_E3b__*/metrics.json")]
    h6 = pd.DataFrame([{"scope": m["dataset"].replace("_to_", "->"), "method": m["method"],
                        "macro_f1": m["metrics"]["macro_f1"], "macro_f1_six": m["metrics"]["macro_f1_six"]} for m in meta])
    out.append("\n\n## Table: cross-mode, default and six-class macro-F1 (mean ± sd over 5 seeds, 13_checks.py H6)\n")
    g = h6.groupby(["scope", "method"])[["macro_f1", "macro_f1_six"]].agg(["mean", "std"]).round(3)
    g.columns = [f"{a}_{b}" for a, b in g.columns]
    out.append(g.reset_index().to_markdown(index=False))
    sens = pd.read_csv(RES / "sensitivity.csv")
    out.append("\n\n## Table: sensitivity, six-class macro-F1 (07_sensitivity.py)\n")
    out.append(sens.pivot_table(index=["factor", "value"], columns=["model", "direction"], values="macro_f1_six")
               .round(3).to_markdown())
text = "\n".join(out)
(RES / "tables.md").write_text(text, encoding="utf-8")
print(text)
